<script lang="ts">
  import { onMount } from 'svelte';
  import { context, trace } from '@opentelemetry/api';
  type Product = {id:string;name:string;description:string;price:number;image_key:string};
  let products = $state<Product[]>([]), selected = $state<Product|null>(null), loading = $state(false), note = $state('Choose an object to see its story.'), elapsed = $state(0), recommendations = $state<string[]>([]), thumbnail = $state(''), trackerUrl=$state(''), trackerConsent=$state(false);
  const tracer=trace.getTracer('sample-gallery-svelte','1.0.0');
  async function action<T>(name:string,perform:(call:(url:string,init?:RequestInit)=>Promise<Response>)=>Promise<T>):Promise<T>{
    const span=tracer.startSpan(name);const scope=trace.setSpan(context.active(),span);
    // Scope each fetch synchronously: browser async context managers need not retain scope across awaits.
    try{return await perform((url,init)=>context.with(scope,()=>fetch(url,init)));}catch(error){span.recordException(error instanceof Error?error:String(error));throw error;}finally{span.end();}
  }
  async function open(product:Product){loading=true;thumbnail='';selected=product;const started=performance.now();try{
    await action('gallery.select_product',async call=>{const response=await call(`/api/products/${product.id}`);if(!response.ok)throw new Error('Could not load product');const data=await response.json();elapsed=Math.round(performance.now()-started);note=data.lookup_count>1?'This product is taking longer to load. A recent catalog change is being recovered.':'Catalog loaded. Ready for a closer look.';
    const rec=await (await call('/api/recommendations')).json();recommendations=rec.items.map((v:{id:string})=>v.id);});
  }catch{note='The catalog is unavailable. Please try again.';}finally{loading=false;}}
  async function makeThumbnail(){if(!selected)return;const id=selected.id;thumbnail='Preparing image metadata…';try{await action('gallery.prepare_thumbnail',async call=>{const job=await(await call(`/api/products/${id}/thumbnail`,{method:'POST'})).json();for(let i=0;i<20;i++){await new Promise(r=>setTimeout(r,300));const status=await(await call(`/api/thumbnails/${job.id}`)).json();if(status.status==='ready'){thumbnail='Image metadata ready · 640 × 480';return;}}thumbnail='Still processing. Try again shortly.';});}catch{thumbnail='Image metadata could not be prepared.';}}
  function loadTracker(){if(!trackerConsent||!trackerUrl)return;const script=document.createElement('script');script.src=trackerUrl;script.onerror=()=>{note='The optional ad simulator failed to load.';};document.head.appendChild(script);}
  onMount(()=>{void action('gallery.browse',async call=>{products=(await(await call('/api/products')).json()).items;trackerUrl=(await(await call('/api/config')).json()).tracker_simulator_url;}).catch(()=>{note='Unable to load the gallery.';});});
</script>
<svelte:head><title>Orbit & Fern · Corridora Gallery</title><meta name="description" content="A small collection of useful objects. A Cloudflare and Corridora sample application." /></svelte:head>
<div class="shell">
  <header><a href="/" class="brand">orbit <span>&</span> fern<span class="dot">.</span></a><span class="eyebrow">OBJECTS WITH A QUIET PURPOSE</span><a href="https://github.com/corridora/sample-gallery" class="source">Source ↗</a></header>
  <main><section class="intro"><div><span class="eyebrow">THE EVERYDAY COLLECTION / 001</span><h1>Small things.<br/><em>Considered living.</em></h1></div><p>Made for the spaces you love.<br/>Explore a few objects that make<br/>the ordinary a little more useful.</p></section>
    <div class="section-label"><span>THE COLLECTION</span><span>{products.length} OBJECTS</span></div>
    <div class="products">{#each products as product}<button class:active={selected?.id===product.id} onclick={()=>open(product)} aria-label={`View ${product.name}`} data-testid={`product-${product.id}`}><div class="image"><img src={`/api/images/${product.image_key}`} alt={product.name} width="640" height="480"/><span class="arrow">↗</span></div><div class="caption"><div><h2>{product.name}</h2><p>{product.description}</p></div><strong>${product.price.toFixed(2)}</strong></div></button>{/each}</div>
    <section class="detail" aria-live="polite"><div><span class="eyebrow">A CLOSER LOOK</span><h2>{selected?.name||'Find your favorite.'}</h2><p data-testid="status">{loading?'Loading the catalog…':note}</p>{#if elapsed && selected}<span class="timing" data-testid="elapsed">Loaded in {elapsed} ms</span>{/if}</div>{#if selected}<div class="tools"><button class="primary" onclick={makeThumbnail} disabled={loading}>Prepare image metadata <span>→</span></button><span data-testid="thumbnail">{thumbnail}</span><small>Pairs well with: {recommendations.join(', ')||'loading…'}</small></div>{/if}</section>
    {#if trackerUrl}<section class="tracker"><label><input type="checkbox" bind:checked={trackerConsent}/> I consent to loading the controlled ad simulator.</label><button onclick={loadTracker} disabled={!trackerConsent}>Load simulator</button><div id="ad-slot"></div></section>{/if}
  </main><footer><span>FICTIONAL OBJECTS. REAL TRACES.</span><span>A Corridora sample · SvelteKit + Cloudflare</span></footer>
</div>
<style>
  :global(body){margin:0;background:#f7f5ee;color:#28312c;font-family:Arial,Helvetica,sans-serif} :global(*){box-sizing:border-box} :global(button),:global(a){-webkit-tap-highlight-color:transparent}.shell{max-width:1280px;margin:auto;padding:0 52px}header{height:114px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #cfcfc2}.brand{font-family:Georgia,serif;font-size:31px;font-weight:bold;letter-spacing:-1.5px;text-decoration:none;color:inherit}.brand span{font-weight:normal}.brand .dot{color:#c46a43}.eyebrow,.section-label,footer{font-size:10px;letter-spacing:1.7px}.source{font-size:12px;color:inherit;text-decoration:none}.intro{padding:68px 0 54px;display:flex;align-items:end;justify-content:space-between}h1{font-size:65px;line-height:1.04;letter-spacing:-2px;font-family:Georgia,serif;font-weight:normal;margin:25px 0 0}h1 em{font-weight:normal;color:#7e8b68}.intro p{font-size:14px;line-height:1.8;margin:0 0 6px;color:#667067}.section-label{display:flex;justify-content:space-between;padding:18px 0;border-top:1px solid #cfcfc2}.products{display:grid;grid-template-columns:repeat(3,1fr);gap:25px}.products button{background:none;border:0;padding:0;cursor:pointer;text-align:left;color:inherit}.image{position:relative;overflow:hidden}.image img{width:100%;height:auto;display:block;transition:transform .25s}.products button:hover img{transform:scale(1.025)}.arrow{position:absolute;right:16px;bottom:16px;background:#f7f5ee;border-radius:50%;width:33px;height:33px;display:grid;place-items:center}.caption{display:flex;justify-content:space-between;gap:10px;padding:20px 0 10px}.caption h2{font-size:16px;margin:0 0 9px}.caption p{font-size:12px;line-height:1.6;color:#687368;margin:0}.caption strong{font-size:13px;font-weight:normal;white-space:nowrap}.active .image{outline:2px solid #6d7d59;outline-offset:4px}.detail{margin:44px 0 50px;padding:33px;background:#e9eddf;display:flex;justify-content:space-between;gap:30px;min-height:195px}.detail h2{font-size:27px;font-family:Georgia,serif;font-weight:normal;margin:15px 0}.detail p{font-size:13px;line-height:1.5;max-width:600px}.timing{font-size:11px;color:#687368}.tools{display:flex;flex-direction:column;gap:13px;justify-content:center;min-width:250px}.primary{background:#344a39;color:white;border:0;padding:14px 18px;cursor:pointer;display:flex;justify-content:space-between;gap:20px}.tools span,.tools small{font-size:11px}.tracker{font-size:12px;padding-bottom:24px}.tracker button{margin-left:12px}footer{border-top:1px solid #cfcfc2;padding:28px 0;display:flex;justify-content:space-between;color:#667067}@media(max-width:760px){.shell{padding:0 22px}header{height:90px}header>.eyebrow{display:none}.intro{display:block;padding:40px 0}.intro p{margin-top:25px}h1{font-size:46px}.products{grid-template-columns:1fr}.detail{display:block;padding:24px}.tools{margin-top:20px}footer{gap:20px;line-height:1.7}}
</style>
